def validar_schema(df, contrato):
    atual = dict(df.dtypes)
    return {
        "faltando": sorted(set(contrato) - set(atual)),
        "sobrando": sorted(set(atual) - set(contrato)),
        "tipo_diferente": {c: (atual[c], t) for c, t in contrato.items() if c in atual and atual[c] != t},
    }

